import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';import vm from 'node:vm';import {scene} from '../scene.mjs';import {pose} from '../model.mjs';
// Test the actual event callbacks with minimal DOM controls, not browser rendering.
function boot(reduced=false){const elements={};let tick;for(const id of ['drawing','phase','angle','sunRead','carrierRead','ringRead','play','reset','ring','carrier','outputLabel','ratio','explain','speed'])elements[id]={value:id==='speed'?'30':'0',attrs:{},setAttribute(k,v){this.attrs[k]=v},addEventListener(k,fn){this['on'+k]=fn}};const context={document:{getElementById:id=>elements[id],addEventListener(){},hidden:false},matchMedia:()=>({matches:reduced}),requestAnimationFrame:fn=>{tick=fn},pose,scene};vm.runInNewContext(fs.readFileSync(new URL('../app.mjs',import.meta.url),'utf8').replace(/^import .*\n/,''),context);return {e:elements,step:n=>tick(n)}}
test('reduced motion starts paused, play then pause maintains frame',()=>{const {e,step}=boot(true);assert.equal(e.play.textContent,'播放');step(0);step(100);assert.equal(e.angle.value,'0.0°');e.play.onclick();step(200);assert.equal(e.angle.value,'3.0°');e.play.onclick();let svg=e.drawing.innerHTML;step(300);assert.equal(e.drawing.innerHTML,svg)});
test('seek and mode switch report correct ratio and reset',()=>{const{e}=boot();e.phase.oninput({target:{value:'360'}});assert.equal(e.carrierRead.textContent,'120.0°');e.carrier.onclick();assert.equal(e.angle.value,'0.0°');assert.equal(e.play.textContent,'播放');e.phase.oninput({target:{value:'360'}});assert.equal(e.ringRead.textContent,'-180.0°');assert.equal(e.carrierRead.textContent,'0.0°');e.reset.onclick();assert.equal(e.ringRead.textContent,'0.0°')});
test('reverse speed, repeated switching, and cyclic render',()=>{const{e,step}=boot();step(0);e.speed.value='-30';step(100);assert.equal(e.angle.value,'2157.0°');for(let i=0;i<10;i++){e.carrier.onclick();e.ring.onclick()}assert.equal(e.ring.attrs['aria-pressed'],'true');assert.equal(e.carrier.attrs['aria-pressed'],'false');assert.notEqual(scene(0),scene(100));});
test('both modes preserve orientations across forward and reverse wrap',()=>{for(const mode of ['ring','carrier'])for(const reverse of [false,true]){const{e,step}=boot(true);e[mode].onclick();e.phase.oninput({target:{value:reverse?'0':'2157'}});e.speed.value=reverse?'-30':'60';e.play.onclick();step(0);step(100);const expected=pose(reverse?-3:2163,mode);for(const part of ['sun','carrier','ring']){const actual=Number(e[part+'Read'].textContent.replace('°',''));const delta=((actual-expected[part])%360+360)%360;assert.ok(Math.min(delta,360-delta)<.01,`${mode} ${reverse} ${part}`)}}});
